(()=>{'use strict';
if(document.body?.dataset.page!=='feedback'||window.__feedbackCommunityLoaded)return;window.__feedbackCommunityLoaded=true;
const API='/api/feedback',reduce=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;if(!document.head.querySelector('link[href*="feedback-identity.css"]')){const css=document.createElement('link');css.rel='stylesheet';css.href='/feedback-identity.css?v=20261027id1';document.head.append(css)}
const escDate=value=>{if(!value)return'';const iso=String(value).includes('T')?String(value):String(value).replace(' ','T')+'Z';const date=new Date(iso);if(Number.isNaN(date.getTime()))return'';return new Intl.DateTimeFormat(undefined,{day:'numeric',month:'short',year:'numeric'}).format(date)};
const thumbPath='M8 10v10H5.5A2.5 2.5 0 0 1 3 17.5v-5A2.5 2.5 0 0 1 5.5 10H8Zm0 0 4.1-6.2a1.7 1.7 0 0 1 3.1 1.2L14.4 8H19a2 2 0 0 1 1.9 2.6l-2 6.5A4 4 0 0 1 15.1 20H8V10Z';
const svgThumb=down=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${thumbPath}"${down?' transform="rotate(180 12 12)"':''}/></svg>`;
const avatarImages={generic:'/assets/avatars/generic.jpg','gas-mask':'/assets/avatars/gas-mask.jpg',trevor:'/assets/avatars/trevor.jpg',franklin:'/assets/avatars/franklin.jpg',michael:'/assets/avatars/michael.jpg',robber:'/assets/avatars/robber.jpg'};
const section=document.createElement('section');section.className='community-feedback-stream';section.setAttribute('aria-labelledby','community-feedback-title');section.innerHTML=`<div class="community-feedback-heading"><div><span class="eyebrow">COMMUNITY VOICES</span><h2 id="community-feedback-title">What players are saying.</h2><p>Feedback shared publicly by Community ID members. Device details and issue reproduction steps always stay private.</p></div></div><div class="community-feedback-controls"><div class="community-feedback-filters" role="group" aria-label="Filter community feedback"><button type="button" class="community-feedback-filter" data-filter="all" aria-pressed="true">All</button><button type="button" class="community-feedback-filter" data-filter="feedback" aria-pressed="false">Feedback</button><button type="button" class="community-feedback-filter" data-filter="issue" aria-pressed="false">Issues</button></div><span class="community-feedback-sort">Newest first</span></div><div class="community-feedback-list" aria-live="polite"><div class="community-feedback-skeleton"></div><div class="community-feedback-skeleton"></div></div>`;
const aside=document.querySelector('.feedback-aside'),main=document.querySelector('.feedback-main');if(aside)aside.insertAdjacentElement('beforebegin',section);else main?.append(section);
const list=section.querySelector('.community-feedback-list'),filters=[...section.querySelectorAll('.community-feedback-filter')];let items=[],filter='all',loading=false;
function addPublicConsent(){const consent=document.querySelector('.feedback-consent');if(!consent||document.querySelector('.feedback-public-share'))return;const label=document.createElement('label');label.className='feedback-public-share';label.innerHTML='<input type="checkbox" name="publicShare" value="yes"><span><strong>Share this feedback publicly</strong><small>Your display name, avatar, summary, message, rating, category and date may appear in Community Voices. Device details and reproduction steps remain private.</small></span>';consent.insertAdjacentElement('afterend',label);try{const saved=JSON.parse(localStorage.getItem('gtav-feedback-draft-v1')||'null');if(saved?.publicShare==='yes'||saved?.publicShare===true)label.querySelector('input').checked=true}catch{}label.querySelector('input').addEventListener('change',()=>document.getElementById('feedback-form')?.dispatchEvent(new Event('change',{bubbles:true})));
 const privacy=document.querySelector('.feedback-privacy');if(privacy)privacy.textContent='Your report and device details are visible to project administrators. Public sharing is optional; if enabled, your Community ID display name and avatar plus the summary, message, rating, category and date are shown publicly. Never include passwords, email addresses, or personal information.';
 const promises=document.querySelector('.feedback-promises');if(promises?.children[1])promises.children[1].lastChild.textContent=' Private by default · public only if you choose';
}
addPublicConsent();const observer=new MutationObserver(addPublicConsent);observer.observe(document.body,{subtree:true,childList:true});
function stars(rating){const value=Math.max(1,Math.min(5,Number(rating)||1));return `<span aria-hidden="true">${'★'.repeat(value)}${'☆'.repeat(5-value)}</span><small>${value}.0</small>`}
function feedAvatar(id){id=avatarImages[id]?id:'generic';const avatar=document.createElement('span');avatar.className=`community-feedback-user-avatar profile-avatar-art avatar-${id}`;const img=document.createElement('img');img.alt='';img.src=avatarImages[id];img.loading='lazy';img.decoding='async';avatar.append(img);return avatar}
function makeCard(item,index){const article=document.createElement('article');article.className='community-feedback-card';article.dataset.kind=item.kind;article.style.transitionDelay=reduce()?'0ms':`${Math.min(index*55,275)}ms`;const target=item.target==='helper'?'Franklin':'Launcher',kind=item.kind==='issue'?'Issue':'Feedback';article.innerHTML=`<div class="community-feedback-meta"><span class="community-feedback-chip kind">${kind}</span><span class="community-feedback-chip">${target}</span><time class="community-feedback-date"></time></div><div class="community-feedback-rating" aria-label="${item.rating} out of 5 stars">${stars(item.rating)}</div><h3></h3><p></p><div class="community-feedback-footer"><span class="community-feedback-author"><span class="community-feedback-author-avatar"></span><span class="community-feedback-author-name"></span></span><div class="community-feedback-reactions"><button type="button" class="feedback-reaction" data-reaction="1" aria-label="Like this feedback" aria-pressed="${item.myReaction===1}">${svgThumb(false)}<span>${item.likes||0}</span></button><button type="button" class="feedback-reaction" data-reaction="-1" aria-label="Dislike this feedback" aria-pressed="${item.myReaction===-1}">${svgThumb(true)}<span>${item.dislikes||0}</span></button></div></div>`;article.querySelector('time').textContent=escDate(item.createdAt);article.querySelector('time').dateTime=item.createdAt||'';article.querySelector('h3').textContent=item.title;article.querySelector(':scope > p').textContent=item.message;article.querySelector('.community-feedback-author-avatar').append(feedAvatar(item.avatar));article.querySelector('.community-feedback-author-name').textContent=item.displayName||'Community member';article.querySelectorAll('.feedback-reaction').forEach(button=>button.addEventListener('click',()=>react(item,button,article)));return article}
function reveal(){const cards=[...list.querySelectorAll('.community-feedback-card')];if(reduce()){cards.forEach(card=>card.classList.add('is-visible'));return}const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');io.unobserve(entry.target)}}),{threshold:.08,rootMargin:'50px'});cards.forEach(card=>io.observe(card))}
function render(){const visible=items.filter(item=>filter==='all'||item.kind===filter);list.replaceChildren();if(!visible.length){const empty=document.createElement('div');empty.className='community-feedback-empty';empty.innerHTML='<strong>No public feedback here yet.</strong><span>New feedback appears after a Community ID member chooses to share it publicly.</span>';list.append(empty);return}visible.forEach((item,index)=>{const card=makeCard(item,index);card.classList.add('is-filtering');list.append(card)});reveal()}
async function load(){if(loading)return;loading=true;try{const response=await fetch(`${API}?feed=1&limit=24`,{credentials:'same-origin',cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'Community feedback is unavailable.');items=Array.isArray(data.items)?data.items:[];render()}catch{list.innerHTML='<div class="community-feedback-empty"><strong>Community feedback is unavailable.</strong><span>Please refresh the page in a moment.</span></div>'}finally{loading=false}}
async function react(item,button,card){if(button.disabled)return;card.querySelectorAll('.feedback-reaction').forEach(b=>b.disabled=true);const reaction=Number(button.dataset.reaction);try{const response=await fetch(API,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'react',reportId:item.id,reaction})}),data=await response.json();if(!response.ok||!data.ok)throw Error(data.error||'Reaction failed');item.likes=Number(data.likes||0);item.dislikes=Number(data.dislikes||0);item.myReaction=Number(data.myReaction||0);const buttons=[...card.querySelectorAll('.feedback-reaction')];buttons.forEach(b=>{const value=Number(b.dataset.reaction);b.setAttribute('aria-pressed',String(item.myReaction===value));b.querySelector('span').textContent=String(value===1?item.likes:item.dislikes)});button.classList.remove('is-popping');void button.offsetWidth;button.classList.add('is-popping');setTimeout(()=>button.classList.remove('is-popping'),380);window.gtavHaptics?.trigger?.('soft')}catch{window.gtavHaptics?.trigger?.('warning')}finally{card.querySelectorAll('.feedback-reaction').forEach(b=>b.disabled=false)}}
filters.forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter||'all';filters.forEach(item=>item.setAttribute('aria-pressed',String(item===button)));render();window.gtavHaptics?.trigger?.('soft')}));window.addEventListener('community-rating-updated',()=>setTimeout(load,250));load();
})();
